# owner: platform
"""Lay students out in seating rows."""


def _sort_key(student):
    return (student.last_name, student.first_name)


def _format_rows(chunks):
    return [
        f"Row {index}: " + " | ".join(names)
        for index, names in enumerate(chunks, 1)
    ]


def seat_rows(students, seats):
    if seats < 1 or not students:
        raise ValueError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    names = [item.display_name for item in ordered]
    starts = range(0, len(names), seats)
    chunks = [names[spot:spot + seats] for spot in starts]
    return _format_rows(chunks)

